import React, { useState, useEffect, useMemo } from 'react';
import { Camera, Check, Film, Music, Plus, Settings, Users, Clock, Edit, XCircle, Trash2, Calendar, Sparkles, AlertTriangle, CheckCircle2, ChevronRight, Hourglass } from 'lucide-react';
import { fetchTasks, fetchNotes, fetchMilestones, fetchSystemStatus, addNote as apiAddNote, updateNote, updateTask, updateMilestone } from './api';
import ShotList from './components/ShotList';
import ProductionTimeline from './components/ProductionTimeline';
import TasksPage from './components/TasksPage';
import ConceptBoard from './components/ConceptBoard';
import ScriptReader from './components/ScriptReader';
import AdminSettings from './components/AdminSettings';
import StickyNotes from './components/StickyNotes';

// Updated color scheme based on your preferences
const colors = {
  primary: '#ff3d7f',       // Vibrant pink
  primaryLight: '#ff9db8',  // Lighter pink
  primaryDark: '#9c6172',   // Darker pink
  secondary: '#121212',     // Deeper black
  secondaryLight: '#212121',// Light black
  light: '#ffffff',         // White
  midGray: '#868686',       // Mid gray
  accent: '#00dbdd',        // Teal accent (cyan blue)
  successGreen: '#4ADE80',  // Green for completed items
  warningOrange: '#dc6300', // Orange for warnings
  errorRed: '#FF3D3D'       // Red for errors/delete
};

// Piano key configuration - made wider
const pianoKeys = [
  { id: 'overview', label: 'Overview', isBlack: false },
  { id: 'timeline', label: 'Timeline', isBlack: true },
  { id: 'tasks', label: 'Tasks', isBlack: false },
  { id: 'shots', label: 'Shots', isBlack: true },
  { id: 'concepts', label: 'Concepts', isBlack: false },
  { id: 'notes', label: 'Notes', isBlack: true },
  { id: 'scriptreader', label: 'Script Reader', isBlack: false },
];

// Custom scrollbar styles and animations
const customScrollbarStyles = `
  .custom-scrollbar::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  
  .custom-scrollbar::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2);
    border-radius: 10px;
  }
  
  .custom-scrollbar::-webkit-scrollbar-thumb {
    background: linear-gradient(to bottom, ${colors.primary}, ${colors.accent});
    border-radius: 10px;
    border: 2px solid transparent;
    background-clip: content-box;
  }
  
  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(to bottom, ${colors.primaryLight}, ${colors.accent});
    background-clip: content-box;
  }
  
  /* Glow animation for active timeline */
  @keyframes glow {
    0% { box-shadow: 0 0 15px currentColor; }
    50% { box-shadow: 0 0 25px currentColor, 0 0 35px currentColor; }
    100% { box-shadow: 0 0 15px currentColor; }
  }
  
  /* Ensure sticky notes persist */
  .sticky-notes-container {
    /* Add any additional styles needed for sticky notes */
  }
`;

function App() {
  const [activeTab, setActiveTab] = useState('overview');
  const [activeNotesView, setActiveNotesView] = useState('todos');

  // Initialize tasks from localStorage or as empty array
  const [tasks, setTasks] = useState(() => {
    const savedTasks = localStorage.getItem('melodicJustice_tasks');
    return savedTasks ? JSON.parse(savedTasks) : [];
  });
  
  // Initialize notes from localStorage or as empty array
  const [notes, setNotes] = useState(() => {
    const savedNotes = localStorage.getItem('melodicJustice_notes');
    return savedNotes ? JSON.parse(savedNotes) : [];
  });
  
  const [milestones, setMilestones] = useState(() => {
    const savedMilestones = localStorage.getItem('melodicJustice_milestones');
    return savedMilestones ? JSON.parse(savedMilestones) : [
      { id: 1, name: 'Pre-Production', completed: false, active: true, description: 'Character design, storyboarding, and initial setup', targetDate: '2025-06-01', order: 1 },
      { id: 2, name: 'Production', completed: false, active: false, description: 'Animation, modeling, and scene assembly', targetDate: '2025-09-01', order: 2 },
      { id: 3, name: 'Post-Production', completed: false, active: false, description: 'Rendering, effects, music, and final touches', targetDate: '2025-12-01', order: 3 }
    ];
  });

  // Initialize systemStatus with default values to prevent undefined errors
  const [systemStatus, setSystemStatus] = useState({
    storage: { total: 0, used: 0, percentage: 0 },
    backup: { last_backup: new Date().toISOString(), status: 'OK' },
    render_cache: { total: 0, used: 0, percentage: 0 }
  });

  // Estimated finish date (based on the last milestone's target date)
  const estimatedFinishDate = useMemo(() => {
    const lastMilestone = [...milestones].sort((a, b) => b.order - a.order)[0];
    return lastMilestone ? new Date(lastMilestone.targetDate) : new Date('2025-12-01');
  }, [milestones]);

  // UI state
  const [newNote, setNewNote] = useState('');
  const [editingStatCard, setEditingStatCard] = useState(null);
  const [showAddNoteModal, setShowAddNoteModal] = useState(false);
  const [showAdminSettings, setShowAdminSettings] = useState(false);
  
  // Piano key sound effect state
  const [keySound, setKeySound] = useState(null);
  
  // Initialize project stats from localStorage or with defaults
  const [projectStats, setProjectStats] = useState(() => {
    const savedStats = localStorage.getItem('melodicJustice_projectStats');
    return savedStats ? JSON.parse(savedStats) : {
      scenes: { total: 24, completed: 0, label: 'Scenes Completed', iconType: 'film' },
      characters: { total: 6, completed: 0, label: 'Characters Rigged', iconType: 'users' },
      shots: { total: 300, completed: 0, label: 'Shots Animated', iconType: 'camera' },
      music: { total: 8, completed: 0, label: 'Music Tracks', iconType: 'music' }
    };
  });

  // Priority tasks is a derived state
  const priorityTasks = useMemo(() => {
    // Get tasks for the active milestone
    const activeMilestoneName = milestones.find(m => m.active)?.name || 'Pre-Production';
    const milestoneTasks = tasks.filter(task => task.milestone === activeMilestoneName);
    
    // Sort by priority: show incomplete tasks first, in order they appear (natural order)
    const incompleteTasks = milestoneTasks.filter(task => !task.completed);
    const nextUpTasks = incompleteTasks.slice(0, 5); // Show next 5 tasks to work on
    
    return nextUpTasks;
  }, [tasks, milestones]);

  // Initialize audio for piano key sounds
  useEffect(() => {
    // Create audio context for piano key sounds
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    
    // Define piano key frequencies (C4 to A4)
    const frequencies = [261.63, 277.18, 293.66, 311.13, 329.63, 349.23];
    
    setKeySound(() => {
      // Return a function that plays a piano note when called
      return (index) => {
        const oscillator = audioContext.createOscillator();
        const gainNode = audioContext.createGain();
        
        oscillator.type = 'sine';
        oscillator.frequency.value = frequencies[index % frequencies.length];
        
        gainNode.gain.value = 0.1;
        gainNode.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + 0.5);
        
        oscillator.connect(gainNode);
        gainNode.connect(audioContext.destination);
        
        oscillator.start();
        oscillator.stop(audioContext.currentTime + 0.5);
      };
    });
    
    return () => {
      // Cleanup
      if (audioContext && audioContext.state !== 'closed') {
        audioContext.close();
      }
    };
  }, []);
  
  const getIcon = (iconType) => {
    switch(iconType) {
      case 'film': return <Film className="w-6 h-6" />;
      case 'users': return <Users className="w-6 h-6" />;
      case 'camera': return <Camera className="w-6 h-6" />;
      case 'music': return <Music className="w-6 h-6" />;
      default: return null;
    }
  };

  // Inject custom scrollbar styles
  useEffect(() => {
    const styleElement = document.createElement('style');
    styleElement.innerHTML = customScrollbarStyles;
    document.head.appendChild(styleElement);
    
    return () => {
      document.head.removeChild(styleElement);
    };
  }, []);
  
  // Save data to localStorage when it changes
  useEffect(() => {
    localStorage.setItem('melodicJustice_tasks', JSON.stringify(tasks));
  }, [tasks]);
  
  useEffect(() => {
    localStorage.setItem('melodicJustice_notes', JSON.stringify(notes));
  }, [notes]);
  
  useEffect(() => {
    localStorage.setItem('melodicJustice_milestones', JSON.stringify(milestones));
  }, [milestones]);
  
  useEffect(() => {
    localStorage.setItem('melodicJustice_projectStats', JSON.stringify(projectStats));
  }, [projectStats]);
  
  // Load data from API if available
  useEffect(() => {
    const loadData = async () => {
      try {
        const fetchedTasks = await fetchTasks();
        if (fetchedTasks && fetchedTasks.length > 0) setTasks(fetchedTasks);
        
        const fetchedNotes = await fetchNotes();
        if (fetchedNotes && fetchedNotes.length > 0) setNotes(fetchedNotes);
        
        const fetchedMilestones = await fetchMilestones();
        if (fetchedMilestones && fetchedMilestones.length > 0) setMilestones(fetchedMilestones);
        
        const status = await fetchSystemStatus();
        if (status) {
          setSystemStatus(status);
        }
      } catch (error) {
        console.error("Error loading data from API, using localStorage instead:", error);
      }
    };
    
    // Try to load from API, but don't worry if it fails - we'll use localStorage
    loadData();
  }, []);

  // Function to check if milestone should advance
  const checkMilestoneAdvancement = (updatedTasks) => {
    const activeMilestone = milestones.find(m => m.active);
    if (!activeMilestone) return;
    
    const milestoneTasks = updatedTasks.filter(task => task.milestone === activeMilestone.name);
    const allTasksComplete = milestoneTasks.length > 0 && milestoneTasks.every(task => task.completed);
    
    if (allTasksComplete) {
      // Find the next milestone to advance to
      const currentIndex = milestones.findIndex(m => m.id === activeMilestone.id);
      const nextIndex = currentIndex + 1;
      
      // If there's a next milestone, make it active
      if (nextIndex < milestones.length) {
        const nextMilestoneId = milestones[nextIndex].id;
        toggleMilestone(nextMilestoneId);
      }
    }
  };
  
  // Handler functions
  const addNoteHandler = async () => {
    if (newNote.trim() !== '') {
      try {
        const noteData = { 
          id: notes.length > 0 ? Math.max(...notes.map(n => n.id)) + 1 : 1,
          text: newNote, 
          completed: false,
          createdAt: new Date().toISOString()
        };
        
        // Try API first
        try {
          const savedNote = await apiAddNote(noteData);
          setNotes([...notes, savedNote]);
        } catch (apiError) {
          // Fall back to localStorage if API fails
          setNotes([...notes, noteData]);
        }
        
        setNewNote('');
        setShowAddNoteModal(false);
      } catch (error) {
        // Final fallback
        const noteData = { 
          id: notes.length > 0 ? Math.max(...notes.map(n => n.id)) + 1 : 1,
          text: newNote, 
          completed: false,
          createdAt: new Date().toISOString()
        };
        setNotes([...notes, noteData]);
        setNewNote('');
        setShowAddNoteModal(false);
        console.error("Failed to add note to API, using localStorage instead");
      }
    }
  };
  
  const toggleNoteComplete = async (id) => {
    try {
      const note = notes.find(n => n.id === id);
      const updatedNote = { ...note, completed: !note.completed };
      
      // Try API first
      try {
        await updateNote(id, updatedNote);
      } catch (apiError) {
        // API not available, that's okay
      }
      
      // Update local state regardless
      setNotes(notes.map(note => 
        note.id === id ? updatedNote : note
      ));
    } catch (error) {
      console.error("Failed to update note:", error);
    }
  };
  
  const deleteNote = async (id) => {
    try {
      // Remove from local state first for instant feedback
      setNotes(notes.filter(note => note.id !== id));
      
      // Then try to remove from backend
      try {
        // await apiDeleteNote(id);
      } catch (apiError) {
        // API not available, that's okay
      }
    } catch (error) {
      console.error("Failed to delete note:", error);
    }
  };
  
  const toggleMilestone = async (id) => {
    try {
      // Try API first
      try {
        await updateMilestone(id);
      } catch (apiError) {
        // API not available, that's okay
      }
      
      // Update local state regardless
      setMilestones(milestones.map(milestone => 
        milestone.id === id ? { ...milestone, active: true } : { ...milestone, active: false }
      ));
    } catch (error) {
      console.error("Failed to update milestone:", error);
    }
  };
  
  const toggleTaskComplete = async (id) => {
    try {
      const task = tasks.find(t => t.id === id);
      const updatedTask = { ...task, completed: !task.completed };
      
      // Update local state immediately for responsive UI
      const updatedTasks = tasks.map(task => 
        task.id === id ? updatedTask : task
      );
      setTasks(updatedTasks);
      
      // Check if we should advance to the next milestone
      checkMilestoneAdvancement(updatedTasks);
      
      // Try to update server state
      try {
        await updateTask(id, updatedTask);
      } catch (apiError) {
        // API not available, that's okay
      }
    } catch (error) {
      console.error("Failed to update task:", error);
    }
  };

  // Function to handle piano key click
  const handlePianoKeyClick = (key, index) => {
    setActiveTab(key.id);
    
    // Play sound if keySound is available
    if (keySound) {
      keySound(index);
    }
  };

  // New function to handle stat card editing
  const updateStatCard = (key, updates) => {
    setProjectStats(prev => ({
      ...prev,
      [key]: {
        ...prev[key],
        ...updates
      }
    }));
    setEditingStatCard(null);
  };

  // Add new task function
  const addTask = async (taskData) => {
    try {
      // Generate a new ID
      const newId = tasks.length > 0 ? Math.max(...tasks.map(t => t.id)) + 1 : 1;
      const newTask = { 
        ...taskData, 
        id: newId,
        createdAt: new Date().toISOString()
      };
      
      // Update local state
      const updatedTasks = [...tasks, newTask];
      setTasks(updatedTasks);
      
      // Try API if needed
      try {
        // await apiAddTask(newTask);
      } catch (apiError) {
        // API not available, that's okay
      }
      
      return newTask;
    } catch (error) {
      console.error("Failed to add task:", error);
      return null;
    }
  };

  // Delete task function
  const deleteTask = async (id) => {
    try {
      // Update local state
      setTasks(tasks.filter(task => task.id !== id));
      
      // Try API if needed
      try {
        // await apiDeleteTask(id);
      } catch (apiError) {
        // API not available, that's okay
      }
    } catch (error) {
      console.error("Failed to delete task:", error);
    }
  };

  // Filter tasks based on active milestone
  const activeMilestoneName = milestones.find(m => m.active)?.name || 'Pre-Production';
  const filteredTasks = tasks.filter(task => task.milestone === activeMilestoneName);

  // Calculate overall project progress for timeline
  const calculateProgress = () => {
    if (tasks.length === 0) return 0;
    
    const completedTasks = tasks.filter(task => task.completed).length;
    return Math.round((completedTasks / tasks.length) * 100);
  };

  // Format storage size for display
  const formatBytes = (bytes, decimals = 2) => {
    if (bytes === 0 || bytes === undefined) return '0 Bytes';
    
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    
    return parseFloat((bytes / Math.pow(k, i)).toFixed(decimals)) + ' ' + sizes[i];
  };

  // Format date for display
  const formatDate = (date) => {
    if (!date) return "Unknown";
    
    const options = { year: 'numeric', month: 'short', day: 'numeric' };
    return new Date(date).toLocaleDateString(undefined, options);
  };

  // Handler for AdminSettings updates
  const handleUpdateSettings = async (newSettings) => {
    try {
      // Save settings to localStorage
      localStorage.setItem('melodicJustice_adminSettings', JSON.stringify(newSettings));
      
      // Optionally, save to backend if you have an API endpoint
      // await axios.post('/api/settings', newSettings);
      
      console.log('Settings updated successfully');
    } catch (error) {
      console.error('Failed to update settings:', error);
      throw error;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gradient-to-br from-gray-900 to-gray-800">
      {/* Pink header with gradient effect */}
      <div className="w-full py-4 border-b-4 border-pink-400 bg-gradient-to-r from-pink-600 to-purple-600 shadow-xl">
        <div className="max-w-6xl mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="relative">
              <img 
                src="/logo192.png" 
                alt="Melodic Justice Logo"
                className="h-16 w-auto mr-3 hover-scale drop-shadow-lg transition-all hover:rotate-3"
              />
              <div className="absolute -top-1 -right-1 h-4 w-4 bg-accent rounded-full animate-pulse"></div>
            </div>
            <div>
              <h1 className="text-white text-2xl font-bold drop-shadow-md tracking-wider">MELODIC JUSTICE</h1>
              <p className="text-pink-100 text-sm drop-shadow-sm">Animation Pipeline Dashboard</p>
            </div>
          </div>
          
          {/* Project timeline and dates */}
          <div className="text-white flex items-center gap-3">
            <div className="flex items-center gap-2 bg-black bg-opacity-20 px-4 py-2 rounded-full shadow-inner">
              <Clock className="mr-1 w-4 h-4" />
              <span className="font-medium">{new Date().toLocaleDateString()}</span>
            </div>
            
            <div className="flex items-center gap-2 bg-black bg-opacity-20 px-4 py-2 rounded-full shadow-inner">
              <Calendar className="mr-1 w-4 h-4" />
              <span className="font-medium">Started: Jul 25, 2023</span>
            </div>
            
            <div className="flex items-center gap-2 bg-black bg-opacity-20 px-4 py-2 rounded-full shadow-inner">
              <Hourglass className="mr-1 w-4 h-4" />
              <span className="font-medium">Finish: {formatDate(estimatedFinishDate)}</span>
            </div>
          </div>
        </div>
      </div>
      
      <div className="max-w-6xl mx-auto px-4 py-6 flex-grow w-full">
        {/* Piano Key Navigation - Enhanced with animations and glow effects */}
        <div className="mb-8 relative overflow-hidden fade-in">
          <div className="flex justify-center gap-1">
            {pianoKeys.map((key, index) => (
              <div 
                key={key.id} 
                className={`relative ${index > 0 ? '' : ''}`}
              >
                <button
                  onClick={() => handlePianoKeyClick(key, index)}
                  className={`
                    border-2 shadow-lg transition-all duration-300 
                    ${key.isBlack 
                      ? 'bg-gray-900 text-white z-10 h-20 relative transform border-gray-700' 
                      : 'bg-white text-gray-900 z-0 h-32 border-gray-300'
                    }
                    ${activeTab === key.id 
                      ? key.isBlack 
                        ? 'bg-gradient-to-b from-purple-900 to-purple-700 border-purple-500 scale-105' 
                        : 'bg-gradient-to-b from-pink-100 to-pink-50 border-pink-400 scale-105' 
                      : ''
                    }
                    hover:shadow-xl hover:scale-105 transform transition-all rounded-b-lg
                  `}
                  style={{
                    width: key.isBlack ? '9rem' : '12rem',
                    marginLeft: key.isBlack ? '-4.5rem' : '0',
                    marginRight: key.isBlack ? '-4.5rem' : '0',
                    boxShadow: activeTab === key.id 
                      ? key.isBlack 
                        ? '0 0 30px rgba(168, 85, 247, 0.7)' 
                        : '0 0 30px rgba(255, 61, 127, 0.5)' 
                      : '0 4px 6px rgba(0,0,0,0.1)'
                  }}
                >
                  <div className={`absolute ${key.isBlack ? 'bottom-3' : 'bottom-6'} w-full text-center text-sm font-bold`}>
                    {key.label}
                  </div>
                  
                  {/* Active indicator */}
                  {activeTab === key.id && (
                    <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2">
                      <div className="w-2 h-2 rounded-full bg-pink-500 animate-pulse"></div>
                    </div>
                  )}
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* Timeline Tab */}
        {activeTab === 'timeline' && (
          <div className="rounded-lg p-6 tab-content fade-in shadow-2xl" style={{ backgroundColor: colors.secondary }}>
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-white mb-2">Production Timeline</h2>
              <p className="text-gray-400">Track your project's progress through major production phases</p>
            </div>
            
            {/* Enhanced timeline with animations and better visuals - Made more skinny and animated */}
            <div className="mb-8 relative">
              <div className="h-20 bg-gray-800 rounded-xl overflow-hidden shadow-inner relative">
                {/* Animated background track */}
                <div className="absolute top-1/2 left-0 right-0 h-1 bg-gray-700 transform -translate-y-1/2 rounded-full">
                  <div className="absolute inset-0 bg-gradient-to-r from-transparent via-gray-600 to-transparent opacity-50 animate-pulse"></div>
                </div>
                
                {/* Timeline markers - milestone points */}
                {milestones.sort((a, b) => a.order - b.order).map((milestone, index) => {
                  const position = (index / (milestones.length - 1)) * 100;
                  
                  return (
                    <div 
                      key={milestone.id}
                      className="absolute top-1/2 transform -translate-y-1/2 transition-all duration-500"
                      style={{ left: `${position}%` }}
                    >
                      <div className={`
                        w-6 h-6 rounded-full flex items-center justify-center text-white text-xs font-bold cursor-pointer
                        transform transition-all duration-300 hover:scale-125
                        ${milestone.active ? 'scale-110 animate-pulse' : 'scale-100'}
                        ${milestone.completed ? 'bg-green-500 shadow-green-500/50' : milestone.active ? 'bg-pink-500 shadow-pink-500/50' : 'bg-gray-600 shadow-gray-600/30'}
                      `}
                      onClick={() => toggleMilestone(milestone.id)}
                      style={{
                        boxShadow: `0 0 ${milestone.active ? '15px' : '8px'} currentColor`,
                        animation: milestone.active ? 'glow 2s infinite alternate' : 'none'
                      }}
                      >
                        {milestone.completed ? <CheckCircle2 className="h-4 w-4" /> : index + 1}
                      </div>
                      
                      <div className="absolute -bottom-8 left-1/2 transform -translate-x-1/2 whitespace-nowrap">
                        <div className={`text-xs font-medium transition-colors ${milestone.active ? 'text-pink-400' : 'text-white'}`}>
                          {milestone.name}
                        </div>
                        <div className="text-xs text-gray-400">{formatDate(milestone.targetDate)}</div>
                      </div>
                      
                      {/* Animated connection lines */}
                      {index < milestones.length - 1 && (
                        <div 
                          className="absolute top-1/2 h-1 transform -translate-y-1/2 rounded-full transition-all duration-500"
                          style={{
                            left: '100%',
                            width: `${(100 / (milestones.length - 1)) - 6}%`,
                            background: milestone.completed 
                              ? 'linear-gradient(to right, #4ADE80, #22c55e)'
                              : milestone.active
                                ? 'linear-gradient(to right, #EC4899, #6B7280)'
                                : 'linear-gradient(to right, #4B5563, #4B5563)',
                            opacity: milestone.completed || milestone.active ? 1 : 0.6
                          }}
                        >
                          {/* Animated flowing dots for active milestone */}
                          {milestone.active && (
                            <div className="absolute top-1/2 transform -translate-y-1/2 w-1 h-1 bg-white rounded-full opacity-75">
                              <div className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></div>
                            </div>
                          )}
                        </div>
                      )}
                      
                      {/* Pulsing indicator for active milestone */}
                      {milestone.active && (
                        <div className="absolute top-1/2 transform -translate-y-1/2 left-6">
                          <div className="h-3 w-3 bg-pink-500 rounded-full opacity-75 animate-ping"></div>
                        </div>
                      )}
                    </div>
                  );
                })}
                
                {/* Animated progress indicator */}
                <div 
                  className="absolute top-0 h-full bg-gradient-to-r from-pink-500/20 to-cyan-500/20 backdrop-filter backdrop-blur-sm border-r-2 border-pink-500 you-are-here pointer-events-none transition-all duration-1000"
                  style={{ 
                    left: 0,
                    width: `${calculateProgress()}%`,
                    boxShadow: '0 0 15px rgba(255,61,127,0.5)'
                  }}
                >
                  {/* Flowing animation */}
                  <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent animate-pulse"></div>
                </div>
              </div>
              
              {/* Progress percentage display */}
              <div className="text-center mt-8 mb-2">
                <div className="inline-block px-4 py-2 rounded-full bg-gray-800 text-white shadow-lg">
                  <span className="text-lg font-bold">{calculateProgress()}%</span>
                  <span className="text-gray-400 ml-2">Overall Progress</span>
                </div>
              </div>
            </div>
            
            {/* Main timeline component */}
            <ProductionTimeline milestones={milestones} tasks={tasks} />
            
            {/* Add task lists for each milestone category below */}
            <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
              {milestones.map(milestone => (
                <div 
                  key={milestone.id}
                  className={`
                    bg-gray-800 rounded-lg overflow-hidden hover-glow transition-all slide-in-right shadow-lg
                    ${milestone.active ? 'ring-2 ring-pink-500 ring-opacity-50' : ''}`}
                >
                  <div 
                    className={`p-4 border-b border-gray-700 flex justify-between items-center
                      ${milestone.active 
                        ? 'bg-gradient-to-r from-pink-900/40 to-pink-800/20' 
                        : milestone.completed
                          ? 'bg-gradient-to-r from-green-900/40 to-green-800/20'
                          : 'bg-gray-900/50'
                      }
                    `}
                  >
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
                      {milestone.active && <div className="w-2 h-2 rounded-full bg-pink-500 animate-pulse"></div>}
                      {milestone.name}
                    </h3>
                    <button 
                      className="p-2 rounded-full bg-pink-600/80 hover:bg-pink-700 hover-scale transition-all shadow-lg"
                      onClick={() => {
                        setActiveTab('tasks');
                      }}
                    >
                      <Plus className="h-4 w-4 text-white" />
                    </button>
                  </div>
                  
                  <div className="p-4 custom-scrollbar overflow-y-auto" style={{ maxHeight: '300px' }}>
                    {/* Show tasks for this milestone */}
                    <div className="space-y-2">
                      {tasks
                        .filter(task => task.milestone === milestone.name)
                        .sort((a, b) => a.completed === b.completed ? 0 : a.completed ? 1 : -1)
                        .slice(0, 5) // Only show 5 tasks for better UI
                        .map(task => (
                          <div 
                            key={task.id}
                            className={`
                              flex items-center p-3 rounded-lg transition-all
                              ${task.completed 
                                ? 'bg-gray-900/50 hover:bg-gray-800/70' 
                                : 'bg-gray-800/80 hover:bg-gray-700/80 shadow-md'
                              }
                            `}
                          >
                            <div 
                              className="cursor-pointer mr-3 flex-shrink-0 transition-all"
                              onClick={() => toggleTaskComplete(task.id)}
                            >
                              {task.completed ? 
                                <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center transition-all group-hover:scale-110 shadow-md">
                                  <Check className="h-3 w-3 text-white" />
                                </div> : 
                                <div className="h-5 w-5 rounded-full border border-gray-500 hover:border-white transition-all group-hover:scale-110" />
                              }
                            </div>
                            <div className={`${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
                              {task.name}
                            </div>
                          </div>
                        ))}
                      
                      {tasks.filter(task => task.milestone === milestone.name).length === 0 && (
                        <div className="text-center text-gray-500 py-6 px-4 bg-gray-900/40 rounded-lg">
                          <div className="flex justify-center mb-2">
                            <AlertTriangle className="h-8 w-8 text-yellow-500 opacity-50" />
                          </div>
                          No tasks for this milestone... yet.<br />
                          <span className="text-yellow-500/70">Get to work!</span>
                        </div>
                      )}
                      
                      {tasks.filter(task => task.milestone === milestone.name).length > 5 && (
                        <button
                          onClick={() => setActiveTab('tasks')}
                          className="w-full py-2 mt-2 text-center text-gray-400 hover:text-white rounded-lg bg-gray-900/50 hover:bg-gray-700/50 transition-all text-sm"
                        >
                          View {tasks.filter(task => task.milestone === milestone.name).length - 5} more tasks
                        </button>
                      )}
                    </div>
                  </div>
                  
                  {/* Milestone footer with stats */}
                  <div className="p-3 border-t border-gray-800 bg-gray-900/50 flex justify-between text-xs text-gray-400">
                    <div>
                      Target: {formatDate(milestone.targetDate)}
                    </div>
                    <div>
                      {tasks.filter(task => task.milestone === milestone.name && task.completed).length} / {tasks.filter(task => task.milestone === milestone.name).length} tasks
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
              {Object.entries(projectStats).map(([key, stat]) => (
                <div 
                  key={key} 
                  className="rounded-lg p-6 hover-glow transition-all fade-in cursor-pointer shadow-xl"
                  style={{ background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%)' }}
                  onClick={() => {
                    // Link each stat card to the appropriate tab
                    if (key === 'scenes' || key === 'shots') {
                      setActiveTab('shots');
                    } else if (key === 'characters') {
                      setActiveTab('concepts');
                    } else if (key === 'music') {
                      setActiveTab('notes');
                    }
                  }}
                >
                  <div className="flex items-center justify-between pb-3">
                    <span className="text-base font-medium text-gray-300">{stat.label}</span>
                    <div className="flex space-x-3 items-center">
                      <div className="text-pink-400">
                        {getIcon(stat.iconType)}
                      </div>
                      <button 
                        className="p-1 rounded-full hover:bg-gray-800 transition-all"
                        onClick={(e) => {
                          e.stopPropagation();
                          setEditingStatCard(key);
                        }}
                      >
                        <Edit className="h-4 w-4 text-gray-400 hover:text-white" />
                      </button>
                    </div>
                  </div>
                  
                  <div className="text-3xl font-bold text-white mb-3 flex items-end">
                    <span>{stat.completed}</span>
                    <span className="text-lg text-gray-400">/{stat.total}</span>
                    
                    {/* Progress indicator */}
                    <span className="ml-2 text-sm text-gray-400">
                      ({Math.round((stat.completed / stat.total) * 100)}%)
                    </span>
                  </div>
                  
                  <div className="w-full bg-gray-700 h-3 rounded-full overflow-hidden">
                    <div 
                      className="h-full rounded-full animate-progress transition-all duration-1000"
                      style={{ 
                        width: `${(stat.completed / stat.total) * 100}%`,
                        backgroundImage: `linear-gradient(to right, ${colors.accent}, ${colors.primary})`
                      }}
                    ></div>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
              <div className="lg:col-span-2 rounded-lg p-6 fade-in shadow-xl" style={{ background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%)' }}>
                <div className="mb-6">
                  <div className="flex items-center mb-4">
                    <div className="w-2 h-2 rounded-full bg-pink-500 animate-pulse mr-2"></div>
                    <h2 className="text-2xl font-bold text-white">Active: {activeMilestoneName}</h2>
                  </div>
                  
                  <div className="relative h-14 bg-gray-800 rounded-xl mb-8 overflow-hidden shadow-inner">
                    {milestones.sort((a, b) => a.order - b.order).map((milestone, index) => {
                      // Calculate position based on order
                      const totalMilestones = milestones.length;
                      const position = (index / totalMilestones) * 100;
                      const nextPosition = ((index + 1) / totalMilestones) * 100;
                      const width = nextPosition - position;
                      
                      return (
                        <div 
                          key={milestone.id}
                          className="absolute top-0 h-full flex items-center justify-center text-sm font-medium text-white px-3 transition-all cursor-pointer hover:opacity-90"
                          style={{ 
                            left: `${position}%`, 
                            width: `${width}%`,
                            background: milestone.completed 
                              ? 'linear-gradient(135deg, #4ADE80, #22c55e)' 
                              : milestone.active 
                                ? 'linear-gradient(135deg, #EC4899, #be185d)'
                                : 'rgba(75, 75, 75, 0.5)',
                            borderRight: index < totalMilestones - 1 ? '1px solid rgba(255,255,255,0.2)' : 'none',
                            boxShadow: milestone.active ? 'inset 0 0 15px rgba(255,255,255,0.2)' : 'none'
                          }}
                          onClick={() => toggleMilestone(milestone.id)}
                        >
                          <span className="truncate">{milestone.name}</span>
                          
                          {/* Show sparkles on active milestone */}
                          {milestone.active && (
                            <Sparkles className="h-4 w-4 text-white absolute top-1 right-1 opacity-70" />
                          )}
                        </div>
                      );
                    })}
                    
                    {/* Current progress indicator */}
                    <div 
                      className="absolute top-0 h-full w-1 bg-white you-are-here pointer-events-none"
                      style={{ 
                        left: `${calculateProgress()}%`,
                        boxShadow: '0 0 15px rgba(255,255,255,0.8)'
                      }}
                    ></div>
                  </div>
                </div>
                
                <h3 className="text-lg font-medium text-white mb-4 border-b border-gray-800 pb-2 flex items-center">
                  <span>Priority Tasks</span>
                  <div className="ml-2 px-2 py-1 bg-gray-800 rounded-full text-xs text-gray-400">Next Up</div>
                </h3>
                
                <div className="space-y-3 custom-scrollbar overflow-y-auto" style={{ maxHeight: '350px' }}>
                  {priorityTasks.length > 0 ? (
                    priorityTasks.map((task, index) => (
                      <div key={task.id} className="p-4 rounded-lg bg-gray-800 flex items-start hover-glow transition-all shadow-md group">
                        <div className="mr-3 flex items-center">
                          <div className="w-6 h-6 rounded-full bg-gray-700 flex items-center justify-center text-white text-xs font-bold mr-3">
                            {index + 1}
                          </div>
                          <div 
                            className="cursor-pointer flex-shrink-0 transition-all"
                            onClick={() => toggleTaskComplete(task.id)}
                          >
                            {task.completed ? 
                              <div className="h-6 w-6 rounded-full bg-green-500 flex items-center justify-center transition-all shadow-md">
                                <Check className="h-4 w-4 text-white" />
                              </div> : 
                              <div className="h-6 w-6 rounded-full border-2 border-gray-500 hover:border-white transition-all group-hover:border-pink-500" />
                            }
                          </div>
                        </div>
                        <div className="flex-grow">
                          <div className="flex justify-between items-center mb-2">
                            <div>
                              <h3 className={`font-medium ${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
                                {task.name}
                              </h3>
                              {task.category && (
                                <span className="text-sm text-gray-400">{task.category}</span>
                              )}
                            </div>
                            {task.progress !== undefined && (
                              <span className="text-sm text-gray-400">{task.progress}%</span>
                            )}
                          </div>
                          {task.progress !== undefined && (
                           <div className="w-full bg-gray-700 h-2 rounded-full">
                             <div 
                               className="h-full rounded-full animate-progress"
                               style={{ 
                                 width: `${task.progress}%`,
                                 backgroundImage: task.completed 
                                   ? 'linear-gradient(to right, #4ADE80, #22c55e)'
                                   : 'linear-gradient(to right, #3CDFFF, #0891b2)'
                               }}
                             ></div>
                           </div>
                         )}
                       </div>
                       
                       <ChevronRight className="h-5 w-5 text-gray-600 opacity-0 group-hover:opacity-100 transition-opacity" />
                     </div>
                   ))
                 ) : (
                   <div className="p-6 rounded-lg bg-gray-800 text-gray-400 text-center">
                     <CheckCircle2 className="h-10 w-10 text-green-500 opacity-50 mx-auto mb-2" />
                     All current tasks completed! Ready to advance to next milestone.
                   </div>
                 )}
               </div>
               
               <div className="mt-4 flex justify-end">
                 <button 
                   onClick={() => setActiveTab('tasks')}
                   className="px-4 py-2 bg-pink-600/80 hover:bg-pink-700 text-white rounded-lg flex items-center gap-2 shadow-lg hover:shadow-xl transition-all"
                 >
                   <span>View All Tasks</span>
                   <ChevronRight className="h-4 w-4" />
                 </button>
               </div>
             </div>

             <div className="rounded-lg p-6 fade-in shadow-xl" style={{ background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%)' }}>
               <div className="flex items-center justify-between mb-6">
                 <h2 className="text-xl font-bold text-white">Quick Notes</h2>
                 <button
                   className="px-4 py-2 rounded-lg flex items-center gap-2 text-white bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 hover-scale transition-all shadow-md"
                   onClick={() => setShowAddNoteModal(true)}
                 >
                   <Plus className="h-4 w-4" />
                   <span>Add</span>
                 </button>
               </div>
               <div className="space-y-3 mb-6 max-h-72 overflow-y-auto custom-scrollbar pr-1">
                 {notes.length === 0 ? (
                   <div className="text-center text-gray-500 py-6 px-4 bg-gray-800 rounded-lg">
                     <AlertTriangle className="h-10 w-10 text-yellow-500 opacity-50 mx-auto mb-2" />
                     Wtf. No notes? Get to work!
                   </div>
                 ) : (
                   notes.slice(0, 7).map(note => (
                     <div 
                       key={note.id} 
                       className="flex items-start p-3 rounded-lg transition-all shadow-md group"
                       style={{ backgroundColor: note.completed ? 'rgba(42, 42, 42, 0.7)' : 'rgba(33, 33, 33, 0.7)' }}
                     >
                       <div 
                         className="cursor-pointer mr-3 mt-1 transition-all"
                         onClick={() => toggleNoteComplete(note.id)}
                       >
                         {note.completed ? 
                           <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center transition-all shadow-md">
                             <Check className="h-3 w-3 text-white" />
                           </div> : 
                           <div className="h-5 w-5 rounded-full border border-gray-500 hover:border-white transition-all group-hover:border-cyan-500" />
                         }
                       </div>
                       <p className={`text-sm flex-grow ${note.completed ? 'text-gray-400 line-through' : 'text-gray-300'}`}>
                         {note.text}
                       </p>
                       <button 
                         className="p-1 rounded-full hover:bg-gray-700 transition-all ml-2 opacity-0 group-hover:opacity-100"
                         onClick={() => deleteNote(note.id)}
                       >
                         <Trash2 className="h-3 w-3 text-gray-500 hover:text-red-400" />
                       </button>
                     </div>
                   ))
                 )}
               </div>
               <button 
                 onClick={() => setActiveTab('notes')}
                 className="w-full py-3 mt-2 text-center text-gray-400 hover:text-white rounded-lg border border-gray-700 hover:border-cyan-500 transition-all hover:bg-gray-800/50 flex items-center justify-center gap-2"
               >
                 <span>View All Notes</span>
                 <ChevronRight className="h-4 w-4" />
               </button>
             </div>
           </div>

           <div className="rounded-lg p-6 fade-in shadow-xl" style={{ background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%)' }}>
             <div className="flex items-center justify-between mb-6">
               <h2 className="text-xl font-bold text-white flex items-center gap-2">
                 System Status
                 <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
               </h2>
               <Settings 
                 className="w-5 h-5 text-gray-400 hover:text-white hover-scale transition-all cursor-pointer" 
                 onClick={() => setShowAdminSettings(true)}
               />
             </div>
             
             {/* Simplified production system status */}
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
               <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all shadow-md">
                 <div className="flex justify-between items-center">
                   <h3 className="text-white font-medium">Storage</h3>
                   <div className="h-3 w-3 bg-green-500 rounded-full pulse"></div>
                 </div>
                 <p className="text-sm text-gray-400 mt-1">
                   {systemStatus?.storage?.used !== undefined ? 
                     `${formatBytes(systemStatus.storage.used)} / ${formatBytes(systemStatus.storage.total)}` : 
                     "Not connected"}
                 </p>
                 <div className="w-full bg-gray-700 h-2 rounded-full mt-2 overflow-hidden">
                   <div 
                     className="h-full rounded-full animate-progress"
                     style={{ 
                       width: `${systemStatus?.storage?.percentage || 0}%`,
                       backgroundImage: 'linear-gradient(to right, #3CDFFF, #00b4d8)'
                     }}
                   ></div>
                 </div>
               </div>
               
               <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all shadow-md">
                 <div className="flex justify-between items-center">
                   <h3 className="text-white font-medium">Backup</h3>
                   <div className="h-3 w-3 bg-green-500 rounded-full pulse"></div>
                 </div>
                 <p className="text-sm text-gray-400 mt-1">
                   {systemStatus?.backup?.last_backup ? 
                     `Last: ${new Date(systemStatus.backup.last_backup).toLocaleDateString()}` : 
                     "Not configured"}
                 </p>
                 <div className="w-full bg-gray-700 h-2 rounded-full mt-2 overflow-hidden">
                   <div 
                     className="h-full rounded-full"
                     style={{ 
                       width: '100%',
                       backgroundImage: 'linear-gradient(to right, #4ADE80, #22c55e)'
                     }}
                   ></div>
                 </div>
               </div>
               
               <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all shadow-md">
                 <div className="flex justify-between items-center">
                   <h3 className="text-white font-medium">Render Cache</h3>
                   <div className="h-3 w-3 bg-green-500 rounded-full pulse"></div>
                 </div>
                 <p className="text-sm text-gray-400 mt-1">
                   {systemStatus?.render_cache?.used !== undefined ? 
                     `${formatBytes(systemStatus.render_cache.used)} / ${formatBytes(systemStatus.render_cache.total)}` : 
                     "Not connected"}
                 </p>
                 <div className="w-full bg-gray-700 h-2 rounded-full mt-2 overflow-hidden">
                   <div 
                     className="h-full rounded-full animate-progress"
                     style={{ 
                       width: `${systemStatus?.render_cache?.percentage || 0}%`,
                       backgroundImage: 'linear-gradient(to right, #f472b6, #ec4899)'
                     }}
                   ></div>
                 </div>
               </div>
               
               <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all shadow-md">
                 <div className="flex justify-between items-center">
                   <h3 className="text-white font-medium">Blender Pipeline</h3>
                   <div className="h-3 w-3 bg-green-500 rounded-full pulse"></div>
                 </div>
                 <p className="text-sm text-gray-400 mt-1">
                   Connected & Ready
                 </p>
                 <div className="w-full bg-gray-700 h-2 rounded-full mt-2 overflow-hidden">
                   <div 
                     className="h-full rounded-full"
                     style={{ 
                       width: '100%',
                       backgroundImage: 'linear-gradient(to right, #a78bfa, #8b5cf6)'
                     }}
                   ></div>
                 </div>
               </div>
             </div>
             
             {/* Simplified Software Status */}
             <div className="bg-gray-800 rounded-lg p-4 shadow-md">
               <h3 className="text-lg font-medium text-white mb-4">Production Software Status</h3>
               <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                 {[
                   { name: 'Blender', status: 'connected', version: '4.0' },
                   { name: 'Rokoko', status: 'warning', version: '2.1' },
                   { name: 'Server', status: 'connected', version: '1.3' },
                   { name: 'Storage', status: 'connected', version: '2.0' }
                 ].map((software) => (
                   <div key={software.name} className="flex items-center justify-between bg-gray-900/70 rounded-lg p-3 shadow-sm hover:shadow-md transition-all">
                     <div>
                       <span className="text-white">{software.name}</span>
                       <span className="text-xs text-gray-400 block">v{software.version}</span>
                     </div>
                     <div 
                       className="h-3 w-3 rounded-full relative"
                       style={{ 
                         backgroundColor: software.status === 'connected' ? colors.successGreen : colors.warningOrange 
                       }}
                     >
                       {/* Ping animation */}
                       <div className="absolute inset-0 rounded-full animate-ping opacity-75" style={{ 
                         backgroundColor: software.status === 'connected' ? colors.successGreen : colors.warningOrange 
                       }}></div>
                     </div>
                   </div>
                 ))}
               </div>
             </div>
           </div>
         </>
       )}

       {/* Tasks Tab */}
       {activeTab === 'tasks' && (
         <TasksPage
           tasks={tasks}
           milestones={milestones}
           onAddTask={addTask}
           onUpdateTask={toggleTaskComplete}
           onDeleteTask={deleteTask}
         />
       )}

       {/* Shots Tab */}
       {activeTab === 'shots' && (
         <ShotList />
       )}
       
       {/* Notes Tab */}
       {activeTab === 'notes' && (
         <div className="rounded-lg p-6 fade-in shadow-xl" style={{ background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%)' }}>
           <div className="flex justify-between items-center mb-4">
             <div>
               <h2 className="text-2xl font-bold text-white mb-2">Notes & To-Dos</h2>
               <p className="text-gray-400">Keep track of ideas, reminders and production notes</p>
             </div>
             
             {/* Mode toggle */}
             <div className="flex bg-gray-800 rounded-lg p-1 shadow-md">
               <button
                 className={`px-4 py-2 rounded-lg transition-all ${activeNotesView === 'todos' ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400'}`}
                 onClick={() => setActiveNotesView('todos')}
               >
                 Quick To-Dos
               </button>
               <button
                 className={`px-4 py-2 rounded-lg transition-all ${activeNotesView === 'sticky' ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400'}`}
                 onClick={() => setActiveNotesView('sticky')}
               >
                 Sticky Notes
               </button>
             </div>
           </div>
           
           {/* To-Dos View */}
           {activeNotesView === 'todos' && (
             <>
               <div className="flex justify-between items-center mb-4">
                 <h3 className="text-xl font-semibold text-white">Quick To-Dos</h3>
                 <button 
                   className="px-4 py-2 rounded-lg flex items-center gap-2 bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 text-white shadow-md"
                   onClick={() => setShowAddNoteModal(true)}
                 >
                   <Plus className="h-4 w-4" />
                   <span>Add To-Do</span>
                 </button>
               </div>
               
               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                 {notes.length === 0 ? (
                   <div className="col-span-full text-center text-gray-500 py-12 bg-gray-800 rounded-lg">
                     No to-dos yet. Add some!
                   </div>
                 ) : (
                   notes.map(note => (
                     <div 
                       key={note.id} 
                       className="p-4 rounded-lg transition-all shadow-md group hover:shadow-lg"
                       style={{ 
                         backgroundColor: 'rgba(33, 33, 33, 0.6)',
                         borderLeft: `3px solid ${note.completed ? colors.successGreen : colors.accent}`
                       }}
                     >
                       <div className="flex justify-between items-start mb-3">
                         <div 
                           className="cursor-pointer flex items-center group"
                           onClick={() => toggleNoteComplete(note.id)}
                         >
                           {note.completed ? 
                             <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center mr-2 transition-all group-hover:scale-110 shadow-sm">
                               <Check className="h-3 w-3 text-white" />
                             </div> : 
                             <div className="h-5 w-5 rounded-full border border-gray-500 hover:border-white mr-2 transition-all group-hover:scale-110 group-hover:border-cyan-500" />
                           }
                           <span className="text-sm text-gray-400 flex items-center">
                             <Clock className="h-3 w-3 mr-1" />
                             {note.createdAt ? new Date(note.createdAt).toLocaleDateString() : 'No date'}
                           </span>
                         </div>
                         <button 
                           className="p-1 rounded-full hover:bg-gray-700 transition-all opacity-0 group-hover:opacity-100"
                           onClick={() => deleteNote(note.id)}
                         >
                           <Trash2 className="h-4 w-4 text-gray-500 hover:text-red-400" />
                         </button>
                       </div>
                       <p className={`${note.completed ? 'text-gray-400 line-through' : 'text-white'} transition-all`}>
                         {note.text}
                       </p>
                     </div>
                   ))
                 )}
               </div>
             </>
           )}
           
           {/* Sticky Notes View */}
           {activeNotesView === 'sticky' && (
             <StickyNotes 
               existingNotes={notes} 
               onUpdateNotes={(updatedNotes) => {
                 // Optional: implement if you want bidirectional sync between to-dos and sticky notes
                 // For now, we'll keep them separate
               }} 
             />
           )}
         </div>
       )}
       
       {/* Concepts Tab */}
       {activeTab === 'concepts' && (
         <ConceptBoard />
       )}
       
       {/* Script Reader Tab */}
       {activeTab === 'scriptreader' && (
         <ScriptReader />
       )}
       
       {/* Edit Stat Card Modal */}
       {editingStatCard && (
         <div className="fixed inset-0 bg-black bg-opacity-70 backdrop-blur-sm flex items-center justify-center z-50 modal">
           <div className="bg-gray-900 rounded-lg p-6 max-w-md w-full shadow-2xl border border-gray-800">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-lg font-bold text-white">Edit {projectStats[editingStatCard].label}</h3>
               <button 
                 className="text-gray-400 hover:text-white transition-all"
                 onClick={() => setEditingStatCard(null)}
               >
                 <XCircle className="h-5 w-5" />
               </button>
             </div>
             
             <div className="space-y-4">
               <div>
                 <label className="block text-gray-400 mb-1">Label</label>
                 <input 
                   type="text"
                   value={projectStats[editingStatCard].label}
                   onChange={(e) => setProjectStats(prev => ({
                     ...prev,
                     [editingStatCard]: {
                       ...prev[editingStatCard],
                       label: e.target.value
                     }
                   }))}
                   className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 focus:outline-none"
                 />
               </div>
               
               <div className="grid grid-cols-2 gap-4">
                 <div>
                   <label className="block text-gray-400 mb-1">Total</label>
                   <input 
                     type="number"
                     value={projectStats[editingStatCard].total}
                     onChange={(e) => setProjectStats(prev => ({
                       ...prev,
                       [editingStatCard]: {
                         ...prev[editingStatCard],
                         total: parseInt(e.target.value) || 0
                       }
                     }))}
                     className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 focus:outline-none"
                   />
                 </div>
                 
                 <div>
                   <label className="block text-gray-400 mb-1">Completed</label>
                   <input 
                     type="number"
                     value={projectStats[editingStatCard].completed}
                     onChange={(e) => setProjectStats(prev => ({
                       ...prev,
                       [editingStatCard]: {
                         ...prev[editingStatCard],
                         completed: parseInt(e.target.value) || 0
                       }
                     }))}
                     className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 focus:outline-none"
                   />
                 </div>
               </div>
               
               <div className="flex justify-end gap-3 pt-4">
                 <button 
                   className="px-4 py-2 rounded-lg border border-gray-700 text-gray-400 hover:text-white hover:border-gray-500 transition-all"
                   onClick={() => setEditingStatCard(null)}
                 >
                   Cancel
                 </button>
                 <button 
                   className="px-4 py-2 rounded-lg text-white shadow-md hover:shadow-lg transition-all bg-gradient-to-r from-pink-500 to-pink-600"
                   onClick={() => setEditingStatCard(null)}
                 >
                   Save Changes
                 </button>
               </div>
             </div>
           </div>
         </div>
       )}
       
       {/* Add Note Modal */}
       {showAddNoteModal && (
         <div className="fixed inset-0 bg-black bg-opacity-70 backdrop-blur-sm flex items-center justify-center z-50 modal">
           <div className="bg-gray-900 rounded-lg p-6 max-w-md w-full shadow-2xl border border-gray-800">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-lg font-bold text-white">Add New Note</h3>
               <button 
                 className="text-gray-400 hover:text-white transition-all"
                 onClick={() => setShowAddNoteModal(false)}
               >
                 <XCircle className="h-5 w-5" />
               </button>
             </div>
             
             <div className="space-y-4">
               <div>
                 <label className="block text-gray-400 mb-1">Note</label>
                 <textarea 
                   value={newNote}
                   onChange={(e) => setNewNote(e.target.value)}
                   placeholder="Enter your note..."
                   className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white h-32 resize-none focus:ring-2 focus:ring-cyan-500 focus:outline-none"
                 />
               </div>
               
               <div className="flex justify-end gap-3 pt-4">
                 <button 
                   className="px-4 py-2 rounded-lg border border-gray-700 text-gray-400 hover:text-white hover:border-gray-500 transition-all"
                   onClick={() => {
                     setNewNote('');
                     setShowAddNoteModal(false);
                   }}
                 >
                   Cancel
                 </button>
                 <button 
                   className="px-4 py-2 rounded-lg text-white shadow-md hover:shadow-lg transition-all bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600"
                   onClick={addNoteHandler}
                   disabled={!newNote.trim()}
                 >
                   Add Note
                 </button>
               </div>
             </div>
           </div>
         </div>
       )}

       {/* Admin Settings Modal */}
       <AdminSettings
         isOpen={showAdminSettings}
         onClose={() => setShowAdminSettings(false)}
         systemStatus={systemStatus}
         onUpdateSettings={handleUpdateSettings}
       />
     </div>
     
     {/* Footer */}
     <div className="bg-gray-900 border-t border-gray-800 p-3 text-center text-gray-500 text-sm">
       <div className="max-w-6xl mx-auto">
         Melodic Justice Animation Dashboard v1.2 | Made with ❤️ and Claude
       </div>
     </div>
   </div>
 );
}

export default App;
